SELECT CASE WHEN (ts.take_profit - ts.latest_price) < (ts.latest_price - ts.stop_loss) THEN 'RR_LT_1' ELSE 'RR_GE_1' END AS rr_bucket, pp.status, COUNT(*) AS n, SUM(pp.realized_pnl < 0) AS losers, SUM(pp.realized_pnl) AS gross_pnl, AVG((ts.take_profit - ts.latest_price) / ts.latest_price * 100) AS avg_tp_pct, AVG((ts.latest_price - ts.stop_loss) / ts.latest_price * 100) AS avg_sl_pct FROM crypto_ai.paper_position pp JOIN crypto_ai.trade_signal ts ON ts.id = pp.signal_id WHERE pp.closed_at IS NOT NULL AND ts.take_profit IS NOT NULL AND ts.stop_loss IS NOT NULL GROUP BY rr_bucket, pp.status LIMIT 10